import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import {journalLines} from '../live-paper/journal-lines.mjs';import {sealedNativePrefix} from '../live-paper/native-dip-host-v1.mjs';import {atomicJson} from '../execution/ledger.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),session=JSON.parse(fs.readFileSync(path.join(rt,'realtime-session.json'))),name=session.file;if(!/^realtime-[A-Za-z0-9.-]+\.jsonl$/.test(name))throw Error('SCREEN_SOURCE_PATH');
const file=path.join(rt,name),seal=sealedNativePrefix(file),cutoff=Date.now(),from=cutoff-900000,seen=new Set(),markets=new Map(),digest=createHash('sha256');let index=0,excluded=0,allObserved=0;
for(const line of journalLines(file,{endByte:seal.bytes})){const r=JSON.parse(line);if(r.format!=='sig-feed-capture'||r.captureIndex!==index++)throw Error('SCREEN_CAPTURE_SEQUENCE');digest.update(line+'\n');if(r.kind!=='trade_observed')continue;allObserved++;const t=r.trade,observed=Date.parse(r.observedAt),executed=Date.parse(t.executedAt);
 if(!Number.isSafeInteger(t.sequence)||t.sequence<0||typeof t.id!=='string'||!Number.isSafeInteger(t.quantity)||t.quantity<=0||!Number.isFinite(t.price)||!Number.isFinite(executed)||!Number.isFinite(observed)||observed>cutoff||executed>cutoff||executed<from||observed-executed>5000||observed<executed-1000){excluded++;continue;}
 const key=[t.tournamentId,t.marketId,t.exchangeId,t.id,t.sequence].join(':');if(seen.has(key))continue;seen.add(key);let m=markets.get(t.marketId);if(!m){m={marketId:t.marketId,exchangeId:t.exchangeId,trades:0,shares:0,yesNormalizedNotional:0,continuousAtReceipt:0,lastTradeAt:t.executedAt};markets.set(t.marketId,m);}if(m.exchangeId!==t.exchangeId)throw Error('SCREEN_MARKET_SCOPE');m.trades++;m.shares+=t.quantity;m.yesNormalizedNotional+=t.quantity*t.price;m.continuousAtReceipt+=r.continuousAtReceipt===true?1:0;m.lastTradeAt=t.executedAt;
}
const stat=fs.statSync(file);if(stat.dev!==seal.dev||stat.ino!==seal.ino||stat.size<seal.bytes)throw Error('SCREEN_SOURCE_REPLACED');const status=JSON.parse(fs.readFileSync(path.join(rt,'realtime-stats.json'))),byId=new Map(status.markets.map(m=>[m.marketId,m]));
const ranked=[...markets.values()].sort((a,b)=>b.shares-a.shares||b.trades-a.trades).map(m=>({...m,currentBookReady:byId.get(m.marketId)?.ready===true,readinessReasons:byId.get(m.marketId)?.reasons??[],marketState:byId.get(m.marketId)?.state??'unknown'}));
const report={at:new Date(cutoff).toISOString(),from:new Date(from).toISOString(),mode:'read_only_live_trade_liquidity_screen',source:{file:name,bytes:seal.bytes,sha256:digest.digest('hex'),records:index},allObserved,excluded,ranked,networkRequests:0,contestOrders:0,limitations:['Ranking does not authorize quotes on unready books.','Observed live engine matches only; old session captures and delayed history excluded.','YES-normalized notional is a descriptive volume metric, not account cash or expected profit.']};atomicJson('data/maker-liquidity-screen-20261013.json',report);console.log(JSON.stringify({markets:ranked.length,recentTrades:ranked.reduce((n,m)=>n+m.trades,0),top:ranked.slice(0,8).map(m=>({market:m.marketId,trades:m.trades,shares:m.shares,ready:m.currentBookReady}))}));
